// User updates their profile - write goes to primary node
@Service
public class UserProfileService {
    private final UserRepository repository;
    private final RedisTemplate<String, UserProfile> cache;

    public void updateProfile(Long userId, UserProfile profile) {
        // Write to database immediately
        repository.save(profile);

        // Write to cache - but replication to other cache nodes takes time
        cache.opsForValue().set("profile:" + userId, profile);
        // At this moment, different cache replicas might return old data
    }

    public UserProfile getProfile(Long userId) {
        var cached = cache.opsForValue().get("profile:" + userId);
        // Might return old value if this replica hasn't synced yet
        return cached != null ? cached : repository.findById(userId).orElseThrow();
    }
}

// CP System (e.g., PostgreSQL with synchronous replication)
@Service
public class BankingService {
    @Transactional
    public void transfer(Long fromAccount, Long toAccount, BigDecimal amount) {
        // If replica nodes are unreachable, this throws an exception
        // Better to fail than show inconsistent balance
        accountRepository.debit(fromAccount, amount);
        accountRepository.credit(toAccount, amount);
        // Both operations commit to all replicas or transaction fails
    }
}

// AP System (e.g., Cassandra)
public class SocialFeedService {
    public List<Post> getFeed(Long userId) {
        // Returns posts even if some nodes are partitioned
        // Might miss recent posts from unavailable nodes
        return postRepository.findByUserId(userId);  // eventual consistency
        // Availability prioritized - better to show slightly stale feed
    }
}

@Service
public class ProductService {
    private final ProductRepository repository;
    private final RedisTemplate<String, Product> redisTemplate;

    public Product getProduct(Long id) {
        String cacheKey = "product:" + id;

        // Check cache first
        var cached = redisTemplate.opsForValue().get(cacheKey);
        if (cached != null) {
            return cached;  // cache hit - no database query
        }

        // Cache miss - fetch from database
        var product = repository.findById(id).orElseThrow();

        // Store in Redis with 1-hour expiration
        redisTemplate.opsForValue().set(cacheKey, product, Duration.ofHours(1));
        return product;
    }
}

// MongoDB document - each product can have different fields
public record Product(
    String id,
    String name,
    BigDecimal price,
    Map<String, Object> attributes  // flexible attributes
) {}

@Service
public class ProductService {
    public void saveProduct(Product product) {
        // Problem: no guarantee attributes are consistent
        var attributes = product.attributes();

        // Defensive coding required - field might not exist
        if (attributes.containsKey("weight")) {
            var weight = attributes.get("weight");
            // Weight could be Integer, String, or Double - type safety lost
        }

        // Solution: validate at application layer
        if (product.price() == null || product.price().compareTo(BigDecimal.ZERO) <= 0) {
            throw new IllegalArgumentException("Invalid price");
        }
        repository.save(product);
    }
}
